func TestCleanupRemovesSupersededFiles(t *testing.T) {
	for _, path := range []string{
		"build.sh",
		"clock_audit_test.sh",
		"compiler_test_exec.sh",
		"exec.sh",
		"regenerate-patch.sh",
		"test.sh",
