+		if err != nil {
+			t.Fatalf("parse %s/%s: %v", directory, entry.Name(), err)
+		}
+		for _, declaration := range file.Decls {
+			if function, ok := declaration.(*ast.FuncDecl); ok && function.Recv == nil {
+				functions[function.Name.Name] = entry.Name()
+			}
+		}
+	}
+	return functions
 }

