+	}
+	if err := os.WriteFile(filepath.Join(directory, "consumer.go"), fixture, 0o600); err != nil {
+		t.Fatalf("write external Runner fixture: %v", err)
+	}
+	goExecutable := os.Getenv("GOMAD3_STOCK_GO")
