				if want := test.resumed[strategy]; !reflect.DeepEqual(observed, want) {
					t.Fatalf("resumed retention = %#v, want %#v", observed, want)
				}
				t.Logf("fixed-identity projection: %s", projection)
			})
		}
	}
}

