+			}
+			return false
+		case *ast.Ident:
+			if declaredIn, declared := local[node.Name]; declared && declaredIn != filepath.Base(path) {
+				t.Errorf("%s references %s from %s", path, node.Name, declaredIn)
+			}
+		default:
+		}
+		return true
+	}
+	ast.Inspect(file, inspect)
+}
