func runCampaignShardWith(ctx context.Context, spec CampaignShardSpec, dependencies executionDependencies) (CampaignResult, error) {
	if err := spec.Shard.Validate(); err != nil {
		return CampaignResult{}, err
	}
	opened, err := openCampaignPlan(spec.PlanPath)
	if err != nil {
		return CampaignResult{}, err
	}
	plan := opened.plan
	if plan.RunnerBuild != spec.RunnerBuild {
		return CampaignResult{}, fmt.Errorf("campaign plan Runner build identity %s does not match this Runner %s", plan.RunnerBuild, spec.RunnerBuild)
	}
	if !deterministicio.Default().Matches(plan.IOProfile) {
		return CampaignResult{}, errors.New("campaign plan I/O profile identity does not match this Runner")
	}
	if dependencies.executor == nil {
		identity, err := target.ReadToolchainIdentity(spec.ToolchainRoot)
		if err != nil {
			return CampaignResult{}, err
		}
		if identity.GoVersion != plan.Toolchain.GoVersion || identity.BuildKey != plan.Toolchain.BuildKey || identity.TargetGOOS != plan.Toolchain.TargetGOOS || identity.TargetGOARCH != plan.Toolchain.TargetGOARCH {
			return CampaignResult{}, errors.New("campaign plan toolchain identity does not match the pinned toolchain")
		}
	}
	mountLimits, err := readonlymount.DecodeLimits(deterministicCapturedInputLimits(plan.IOROMountLimits))
	if err != nil {
		return CampaignResult{}, err
	}
	mappings, err := readonlymount.ParseMappings(plan.IOROMounts, opened.path+campaignPlanBundleSuffix)
	if err != nil {
		return CampaignResult{}, err
	}
	mountIdentity, _, err := captureCampaignPlanMounts(mappings, mountLimits)
	if err != nil {
		return CampaignResult{}, fmt.Errorf("verify campaign plan mount identity: %w", err)
	}
	if !equalCampaignPlanMountIdentity(mountIdentity, opened.mounts) {
		return CampaignResult{}, errors.New("campaign plan read-only mount identity changed")
	}
	environment, clockTick, err := campaignPlanEnvironment(plan)
	if err != nil {
		return CampaignResult{}, err
	}
	targetRecord := plan.Prepared.Target
	config := CampaignSpec{
		PlanSHA256: opened.identity, Shard: spec.Shard, Strategy: StrategySeed, Seeds: plan.Selection, Parallel: int(plan.Parallel),
		ExecutionTimeout: time.Duration(plan.ExecutionTimeoutNanos), OverallTimeout: time.Duration(plan.OverallTimeoutNanos), TerminateGrace: time.Duration(plan.TerminateGraceNanos),
		OnFailure: PolicyAll, FailureBudget: uint64(plan.FailureBudget), OutputLimit: uint64(plan.OutputBytes), WorldTransitionLimit: uint64(plan.WorldTransitionBytes),
		Diagnostics: campaignPlanDiagnostics(plan), ChoiceTraceLimit: campaignPlanChoiceLimit(plan.ChoiceProfile), ClockTick: clockTick, IOTranscriptLimit: uint64(plan.IOTranscriptBytes), Artifacts: spec.Artifacts, Environment: environment,
		IOROMounts: campaignPlanRuntimeMountValues(mappings), IOROMountLimits: mountLimits,
		Target: target.Spec{
			Kind: target.Kind(targetRecord.Kind), Source: targetRecord.Source, Args: append([]string(nil), targetRecord.Argv[1:]...), BuildTags: append([]string(nil), targetRecord.BuildTags...),
			WorkingDir: filepath.Dir(opened.path), ToolchainRoot: spec.ToolchainRoot, CapabilityMode: target.CapabilityMode(targetRecord.CapabilityMode),
		},
		SupervisorCommand: append([]string(nil), spec.SupervisorCommand...), RunnerBuild: spec.RunnerBuild,
		Coverage: CoverageMode(plan.Coverage), RequiredSemanticProbes: append([]string(nil), plan.RequiredSemanticProbes...),
		KeepSuccesses: KeepSuccesses(plan.KeepSuccesses), SuccessArtifactLimit: uint64(plan.SuccessArtifactLimit), SuccessBytesLimit: uint64(plan.SuccessBytesLimit),
		Progress: spec.Progress, ProgressInterval: spec.ProgressInterval, Replayer: spec.Replayer,
		Preparer: &campaignPlanPreparer{source: opened.prepared},
	}
	if plan.Guidance != nil {
		config.Guide = true
		config.GuideRegression = plan.Guidance.Regression
		config.Corpus = plan.Guidance.Corpus
		config.GuideSnapshotSHA256 = plan.Guidance.SnapshotSHA256
		config.guidancePlan = plan.Guidance
	}
	return runLocal(ctx, campaignRequestFromSpecWith(config, dependencies))
}

public.body:
func CreateCampaignPlan(ctx context.Context, spec CampaignPlanSpec) (_ CampaignPlanResult, retErr error) {
	return createCampaignPlanWith(ctx, spec, executionDependencies{})
}

private.body:
func createCampaignPlanWith(ctx context.Context, spec CampaignPlanSpec, dependencies executionDependencies) (_ CampaignPlanResult, retErr error) {
	if ctx == nil {
		ctx = context.Background()
	}
	config := campaignRequestFromSpecWith(spec.Campaign, dependencies)
	selection, environment, err := validateCampaignRequest(config)
	if err != nil {
		return CampaignPlanResult{}, err
	}
	if config.strategy() != StrategySeed || config.OnFailure != PolicyAll {
		return CampaignPlanResult{}, errors.New("portable campaign plans require a seed campaign with on-failure=all")
	}
	if config.Shard.Count != 0 || config.PlanSHA256 != "" || config.ResumeCampaign != "" {
		return CampaignPlanResult{}, errors.New("portable campaign plan input cannot already be a shard or resume")
	}
	output, err := filepath.Abs(spec.Output)
	if err != nil || spec.Output == "" {
		return CampaignPlanResult{}, errors.Join(errors.New("resolve campaign plan output"), err)
	}
	bundle := output + campaignPlanBundleSuffix
	for _, path := range []string{output, bundle} {
		if _, err := os.Lstat(path); err == nil {
			return CampaignPlanResult{}, fmt.Errorf("campaign plan output already exists: %s", path)
		} else if !errors.Is(err, os.ErrNotExist) {
			return CampaignPlanResult{}, fmt.Errorf("inspect campaign plan output: %w", err)
		}
	}
	if err := os.MkdirAll(filepath.Dir(output), 0o700); err != nil {
		return CampaignPlanResult{}, fmt.Errorf("create campaign plan parent: %w", err)
	}
	if err := os.Mkdir(bundle, 0o700); err != nil {
		return CampaignPlanResult{}, fmt.Errorf("create campaign plan bundle: %w", err)
	}
	published := false
	defer func() {
		if !published {
			retErr = errors.Join(retErr, os.RemoveAll(bundle))
		}
	}()
	if config.IOROMountLimits == (readonlymount.Limits{}) {
		config.IOROMountLimits = readonlymount.DefaultLimits()
	}
	mounts, err := readonlymount.ParseMappings(config.IOROMounts, config.Target.WorkingDir)
	if err != nil {
		return CampaignPlanResult{}, err
	}
	mounts, portableMounts := canonicalCampaignPlanMounts(mounts)
	mountIdentity, capturedMounts, err := captureCampaignPlanMounts(mounts, config.IOROMountLimits)
	if err != nil {
		return CampaignPlanResult{}, fmt.Errorf("capture campaign plan mount identity: %w", err)
	}
	config.Target.PreparationRoot = bundle
	prepared, err := preparation.Prepare(ctx, preparation.Request{
		Target: config.Target, Environment: config.Environment, Preparer: config.Preparer,
	})
	if err != nil {
		return CampaignPlanResult{}, err
	}
	targetPath := filepath.Join(bundle, campaignPlanTargetFile)
	if filepath.Clean(prepared.Path) != targetPath {
		preparationDirectory := filepath.Dir(prepared.Path)
		relative, relativeErr := filepath.Rel(bundle, preparationDirectory)
		if relativeErr != nil || relative == "." || relative == ".." || filepath.IsAbs(relative) || len(relative) >= 3 && relative[:3] == ".."+string(filepath.Separator) {
			return CampaignPlanResult{}, errors.Join(errors.New("prepared campaign target is outside its private preparation directory"), relativeErr)
		}
		if err := os.Rename(prepared.Path, targetPath); err != nil {
			return CampaignPlanResult{}, fmt.Errorf("publish prepared campaign target: %w", err)
		}
		if err := os.RemoveAll(preparationDirectory); err != nil {
			return CampaignPlanResult{}, fmt.Errorf("remove campaign target preparation files: %w", err)
		}
	}
	if err := os.Chmod(targetPath, 0o500); err != nil {
		return CampaignPlanResult{}, fmt.Errorf("make campaign target immutable: %w", err)
	}
	prepared.Path = targetPath
	if err := prepared.Verify(); err != nil {
		return CampaignPlanResult{}, err
	}
	if err := materializeCampaignPlanMounts(bundle, capturedMounts); err != nil {
		return CampaignPlanResult{}, fmt.Errorf("materialize campaign plan mounts: %w", err)
	}
	if config.Guide {
		config.Corpus, err = guidedCorpusPath(config.Corpus)
		if err != nil {
			return CampaignPlanResult{}, err
		}
		guidance, err := openGuidance(ctx, config, prepared, environment, "plan")
		if err != nil {
			return CampaignPlanResult{}, err
		}
		snapshot := guidance.Snapshot()
		selection, config.guidancePlan, err = selectGuidedSeeds(selection, snapshot, config.Corpus, config.GuideRegression)
		err = errors.Join(err, guidance.Close())
		if err != nil {
			return CampaignPlanResult{}, err
		}
		config.Seeds = selection.String()
		config.GuideSnapshotSHA256 = snapshot.SnapshotSHA256
	}
	journalPlan, err := campaign.DeriveExecutionJournalPlan(string(StrategySeed), selection.Count(), 0, uint64(config.Parallel))
	if err != nil {
		return CampaignPlanResult{}, fmt.Errorf("derive campaign journal capacity: %w", err)
	}
	plan, err := campaignPlanRecord(config, journalPlan, ".prepared/target", prepared, environment, portableMounts, selection.Count())
	if err != nil {
		return CampaignPlanResult{}, err
	}
	if err := campaign.ValidateCampaignPlan(plan); err != nil {
		return CampaignPlanResult{}, err
	}
	document := portableCampaignPlan{Schema: campaignPlanSchema, Mapping: campaignPlanMapping, Mounts: mountIdentity, Campaign: plan}
	encoded, err := canonicaljson.CanonicalJSON(document)
	if err != nil {
		return CampaignPlanResult{}, fmt.Errorf("encode campaign plan: %w", err)
	}
	if len(encoded) > maximumCampaignPlanBytes {
		return CampaignPlanResult{}, fmt.Errorf("campaign plan exceeds its %d-byte capacity", maximumCampaignPlanBytes)
	}
	if err := syncRegularFile(targetPath); err != nil {
		return CampaignPlanResult{}, err
	}
	if err := syncDirectory(bundle); err != nil {
		return CampaignPlanResult{}, err
	}
	if err := publishPlanFile(output, encoded); err != nil {
		return CampaignPlanResult{}, err
	}
	published = true
	return CampaignPlanResult{
		Path: output, BundlePath: bundle, SHA256: record.HashBytes(encoded), SelectionCount: selection.Count(), TargetSHA256: record.SHA256(prepared.SHA256),
	}, nil
}

public.body:
func Replay(ctx context.Context, config ReplaySpec) (ReplayResult, error) {
	return replayWith(ctx, config, executionDependencies{})
}

private.body:
func replayWith(ctx context.Context, config ReplaySpec, dependencies executionDependencies) (result ReplayResult, retErr error) {
	opened, err := preflight(config)
	if err != nil {
		return ReplayResult{}, &ReplayPreflightError{Err: err}
	}
	defer func() {
		if closeErr := opened.Close(); closeErr != nil && retErr == nil {
			result = ReplayResult{}
			retErr = fmt.Errorf("close replay artifact: %w", closeErr)
		}
	}()
	manifest := opened.Manifest()
	if err := target.VerifyCompatibility(manifest.Target.Compatibility); err != nil {
		return ReplayResult{}, &ReplayPreflightError{Err: fmt.Errorf("verify replay compatibility: %w", err)}
	}
	if err := deterministicio.Default().VerifyAdapters(replayAdapters(manifest.Target.Adapters)); err != nil {
		return ReplayResult{}, &ReplayPreflightError{Err: fmt.Errorf("verify replay adapters: %w", err)}
	}
	result = ReplayResult{Artifact: opened.Snapshot(), Verified: true, Diagnostic: manifest.ReplayMode == record.ReplayDiagnostic, ChoiceReplayStatus: ChoiceReplayNone}
	choiceCapability, choiceUnavailable, err := choiceCapabilityForArtifact(opened)
	if err != nil {
		return ReplayResult{}, &ReplayPreflightError{Err: err}
	}
	if choiceUnavailable {
		result.ChoiceReplayStatus = ChoiceReplayUnavailable
		result.Divergence = "choice_profile.replay_unavailable"
		return result, nil
	}
	if choiceCapability != nil {
		result.ChoiceReplayStatus = ChoiceReplayAvailable
	}
	simulationReplay, err := simulationCapabilityForArtifact(opened)
	if err != nil {
		return ReplayResult{}, &ReplayPreflightError{Err: err}
	}
	if config.VerifyOnly {
		return result, nil
	}
	executor := dependencies.executor
	if executor == nil {
		if len(config.SupervisorCommand) == 0 {
			return ReplayResult{}, fmt.Errorf("supervisor command is required")
		}
		executor = replayProcessExecutor{}
	}
	workDirectory, err := os.MkdirTemp("", "gomad3-replay-")
	if err != nil {
		return ReplayResult{}, fmt.Errorf("create replay working directory: %w", err)
	}
	defer func() {
		if cleanupErr := os.RemoveAll(workDirectory); cleanupErr != nil && retErr == nil {
			result = ReplayResult{}
			retErr = fmt.Errorf("remove replay working directory: %w", cleanupErr)
		}
	}()
	if err := os.Chmod(workDirectory, 0o700); err != nil {
		return ReplayResult{}, fmt.Errorf("make replay working directory private: %w", err)
	}
	targetPath := filepath.Join(workDirectory, "target")
	if err := opened.CopyPayload(manifest.Target.File, targetPath, 0o500); err != nil {
		return ReplayResult{}, fmt.Errorf("copy verified replay target: %w", err)
	}
	if err := validateTargetBuildInfo(targetPath, manifest.Target.BuildInfo); err != nil {
		return ReplayResult{}, err
	}
	runTimeout, err := duration(manifest.Limits.ExecutionTimeoutNanos)
	if err != nil {
		return ReplayResult{}, err
	}
	terminateGrace, err := duration(manifest.Limits.TerminateGraceNanos)
	if err != nil {
		return ReplayResult{}, err
	}
	environment := replayEnvironment(manifest.Environment)
	var expectedWorldInitial []byte
	var worldReplayPlan []byte
	if manifest.World.Initial.Schema == "gomad3.world.snapshot/v1" {
		worldPayloads, readErr := readWorldPayloads(opened)
		if readErr != nil {
			return ReplayResult{}, fmt.Errorf("read replay World payloads: %w", readErr)
		}
		initial, final, validateErr := execution.Validate(manifest.World, worldPayloads)
		if validateErr != nil {
			return ReplayResult{}, fmt.Errorf("validate replay World plan: %w", validateErr)
		}
		expectedWorldInitial = worldPayloads.Initial
		worldReplayPlan, err = canonicaljson.CanonicalJSON(world.ReplayPlan{
			SchemaVersion: world.SchemaVersion,
			InitialDigest: initial.StateDigest,
			Transitions:   final.Transitions[len(initial.Transitions):],
			FinalDigest:   final.StateDigest,
		})
		if err != nil {
			return ReplayResult{}, fmt.Errorf("encode replay World plan: %w", err)
		}
	}
	var ioConfig []byte
	var ioTranscriptLimit uint64
	var expectedIOTranscript []byte
	var readOnlyMounts []readonlymount.Mapping
	var readOnlyMountLimits readonlymount.Limits
	readOnlyMountSnapshot := &readonlymount.Snapshot{}
	profile := deterministicio.Default()
	ioConfig, err = profile.BootstrapFrame(target.Prepared{SHA256: string(manifest.Target.SHA256), Argv: append([]string(nil), manifest.Target.Argv...)}, manifest.Runner.RunnerBuild, uint64(manifest.Seed))
	if err != nil {
		return ReplayResult{}, err
	}
	ioTranscriptLimit = uint64(manifest.Limits.IOTranscriptBytes)
	if manifest.IOProfile.Transcript == nil {
		if manifest.ReplayMode != record.ReplayDiagnostic {
			return ReplayResult{}, errors.New("recorded I/O profile has no complete transcript")
		}
		if choiceCapability != nil {
			return ReplayResult{}, errors.New("diagnostic replay without an I/O transcript cannot replay recorded choices")
		}
	}
	readOnlyMountLimits = readonlymount.DefaultLimits()
	if mounts := manifest.IOProfile.ReadOnlyMounts; mounts != nil {
		descriptor, readErr := opened.ReadPayload(mounts.File, uint64(mounts.Bytes))
		if readErr != nil {
			return ReplayResult{}, fmt.Errorf("read read-only mount descriptor: %w", readErr)
		}
		var snapshot readonlymount.Snapshot
		readOnlyMounts, readOnlyMountLimits, snapshot, readErr = readonlymount.DecodeCapturedInputs(replayCapturedInputs(*mounts), descriptor, func(name string, maximum uint64) ([]byte, error) {
			return opened.ReadPayload(name, maximum)
		})
		if readErr != nil {
			return ReplayResult{}, fmt.Errorf("decode read-only mount artifact: %w", readErr)
		}
		readOnlyMountSnapshot = &snapshot
	}
	if transcript := manifest.IOProfile.Transcript; transcript != nil {
		expectedIOTranscript, err = opened.ReadPayload(transcript.File, ioTranscriptLimit)
		if err != nil {
			return ReplayResult{}, fmt.Errorf("read expected I/O transcript: %w", err)
		}
	}
	ioCapability := &execution.IOCapability{
		Config:     ioConfig,
		Transcript: &execution.IOTranscriptCapability{Limit: ioTranscriptLimit, Replay: manifest.IOProfile.Transcript != nil, Expected: expectedIOTranscript},
		ReadOnlyMount: &execution.ReadOnlyMountCapability{
			Mappings: readOnlyMounts, Limits: readOnlyMountLimits, Replay: readOnlyMountSnapshot,
		},
	}
	request := execution.Spec{
		SupervisorCommand: append([]string(nil), config.SupervisorCommand...), Command: targetPath,
		BootstrapCommand: replayBootstrapCommand(config),
		Args:             append([]string(nil), manifest.Target.Argv[1:]...), Argv0: manifest.Target.Argv[0], Dir: workDirectory, Env: environment,
		ExecutionTimeout: runTimeout, TerminateGrace: terminateGrace, OutputLimit: uint64(manifest.Limits.OutputBytes),
		World: execution.WorldCapability{
			RecordLimit: world.MaximumRecordingBytes, TransitionLimit: uint64(manifest.Limits.WorldTransitionBytes),
			Seed: uint64(manifest.Seed), ExpectedInitial: expectedWorldInitial, ReplayPlan: worldReplayPlan,
		},
		IO: ioCapability, Choice: choiceCapability,
	}
	request.Simulation = simulationReplay.capability
	if request.Simulation == nil {
		if _, ok := executor.(replayProcessExecutor); ok {
			request.Simulation = &execution.SimulationCapability{Role: execution.SimulationRoleCoordinator}
		}
	}
	observed, err := executor.Run(ctx, request)
	if config.ObservedDir != "" {
		if dumpErr := dumpObservedStreams(config.ObservedDir, observed); dumpErr != nil {
			return ReplayResult{}, dumpErr
		}
	}
	if err != nil {
		if divergence, controlled := onlyChoiceReplayDivergence(err); controlled {
			result.ChoiceReplayStatus = ChoiceReplayDiverged
			result.Divergence = fmt.Sprintf("choice_profile.divergence.ordinal[%d].%s", divergence.Divergence.Ordinal, choice.DivergenceReasonName(divergence.Divergence.Reason))
			return result, nil
		}
		return ReplayResult{}, fmt.Errorf("execute replay target: %w", err)
	}
	var observedWorld *execution.Bundle
	if len(observed.WorldRecord) != 0 {
		recording, worldErr := world.DecodeRecording(observed.WorldRecord)
		if worldErr != nil {
			return ReplayResult{}, fmt.Errorf("decode replay World record: %w", worldErr)
		}
		if recording.Final.Replay.Expected != 0 && recording.Final.Replay.Cursor != recording.Final.Replay.Expected && recording.Terminal.Kind != world.TerminalReplayDivergence {
			return ReplayResult{}, errors.New("validate replay World record: final World replay is incomplete")
		}
		recording.Initial.Replay = world.ReplayProgress{}
		recording.Final.Replay = world.ReplayProgress{}
		bundle, worldErr := execution.ComposeRecording(recording, uint64(manifest.Limits.WorldTransitionBytes))
		if worldErr != nil {
			return ReplayResult{}, fmt.Errorf("validate replay World record: %w", worldErr)
		}
		observedWorld = &bundle
	}
	result.Divergence = simulationReplay.divergence(manifest, observed)
	if result.Divergence == "" {
		result.Divergence = replayDivergence(manifest, observed, observedWorld)
	}
	result.Match = result.Divergence == ""
	if choiceCapability != nil {
		if choiceTraceDivergence(manifest, observed) == "" {
			result.ChoiceReplayStatus = ChoiceReplayExact
		} else {
			result.ChoiceReplayStatus = ChoiceReplayDiverged
		}
	}
	return result, nil
}

type simulationArtifactReplay struct {
	capability     *execution.SimulationCapability
	expectedRecord []byte
}

public.body:
func Minimize(ctx context.Context, config MinimizeSpec) (MinimizeResult, error) {
	return minimizeWith(ctx, config, executionDependencies{})
}

private.body:
func minimizeWith(ctx context.Context, config MinimizeSpec, dependencies executionDependencies) (result MinimizeResult, retErr error) {
	session, err := openMinimizationSession(ctx, config, dependencies)
	if err != nil {
		return MinimizeResult{}, err
	}
	defer func() {
		retErr = errors.Join(retErr, session.close())
		if retErr != nil {
			result = MinimizeResult{}
		}
	}()
	state, err := session.reduce(ctx)
	if err != nil {
		return MinimizeResult{}, err
	}
	checkpoint := session.workspace.Checkpoint()
	result = MinimizeResult{
		Artifact: session.opened.Snapshot(), Changed: checkpoint.Accepted != nil, Attempts: state.Attempts,
		AttemptBudget: state.AttemptBudget, Accepted: projectMinimizationReductions(state.Accepted), StopReason: string(state.StopReason),
	}
	if checkpoint.Accepted != nil {
		published, err := session.publishMinimized(ctx, checkpoint)
		if err != nil {
			return MinimizeResult{}, err
		}
		result.Artifact = published
	}
	if err := session.workspace.Complete(); err != nil {
		return MinimizeResult{}, err
	}
	return result, nil
}

